/// Get pre-converted frames for computer_fingers animation
pub fn get_computer_fingers_frames() -> Vec<BrailleFrame> {
    let patterns_per_frame = FRAME_WIDTH * FRAME_HEIGHT;
    (0..FRAME_COUNT)
        .map(|i| {
            let start = i * patterns_per_frame;
            let end = start + patterns_per_frame;
            BrailleFrame {
                patterns: PATTERN_DATA[start..end].to_vec(),
                width: FRAME_WIDTH,
                height: FRAME_HEIGHT,
                duration_ms: FRAME_DURATION_MS,
            }
        })
        .collect()
}
